// Анализ показаний датчиков (код сгенерирован с помощью AI и проверен вручную)
// Вход: msg.payload = { student, readings: [числа] }
const input = msg.payload || {};
const readings = Array.isArray(input.readings) ? input.readings : [];
const threshold = 25;            // порог «высокой» температуры, °C

let sum = 0;
let max = -Infinity;
let min = Infinity;
const above = [];                // массив значений выше порога

for (let i = 0; i < readings.length; i++) {
    const value = Number(readings[i]);
    sum += value;
    if (value > max) max = value;
    if (value < min) min = value;
    if (value > threshold) {
        above.push(value);
    }
}

const avg = readings.length > 0 ? sum / readings.length : 0;

let status;
if (readings.length === 0) {
    status = "empty";
} else if (avg > threshold) {
    status = "high";
} else {
    status = "normal";
}

// Результат — объект
const result = {
    student: input.student || "unknown",
    count: readings.length,
    avg: Number(avg.toFixed(2)),
    min: readings.length ? min : null,
    max: readings.length ? max : null,
    aboveThreshold: above,
    status: status
};

msg.topic = "lab2/dusov/function";
msg.payload = result;
return msg;
